<script>
(function () {
  const form      = document.getElementById('otp-form');
  const inputs    = Array.from(form.querySelectorAll('input'));
  const verifyBtn = document.getElementById('verify-btn');
  const timerEl   = document.getElementById('timer');

  /* ---- Move focus between boxes ---- */
  inputs.forEach((input, index) => {
    input.addEventListener('input', function () {
      this.value = this.value.replace(/\D/g, '').slice(0, 1);
      if (this.value && index < inputs.length - 1) {
        inputs[index + 1].focus();
      }
    });

    input.addEventListener('keydown', function (e) {
      if (e.key === 'Backspace' && !this.value && index > 0) {
        inputs[index - 1].focus();
      }
      if (e.key === 'ArrowRight' && index < inputs.length - 1) {
        inputs[index + 1].focus();
      }
      if (e.key === 'ArrowLeft' && index > 0) {
        inputs[index - 1].focus();
      }
    });

    input.addEventListener('paste', function (e) {
      e.preventDefault();
      const data = e.clipboardData.getData('text')
                    .replace(/\D/g, '')
                    .slice(0, 6);
      data.split('').forEach((ch, i) => {
        if (inputs[i]) inputs[i].value = ch;
      });
      const last = Math.min(data.length, 5);
      inputs[last]?.focus();
    });
  });

  /* ---- Submit ---- */
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    const code = inputs.map(i => i.value).join('');
    if (code.length !== 6) return;

    verifyBtn.textContent = 'acco...';
    verifyBtn.disabled = true;

    // Simulate API call
    setTimeout(function () {
      verifyBtn.textContent = 'acco';
      verifyBtn.disabled = false;
    }, 2000);
  });

  /* ---- Countdown (Arabic-Indic digits) ---- */
  const arabicDigits = '٠١٢٣٤٥٦٧٨٩';
  const toArabic = function (n) {
    return n.toString().split('').map(function (d) { return arabicDigits[d]; }).join('');
  };

  let seconds = 45;
  const tick = function () {
    if (seconds < 0) {
      timerEl.textContent = 'أعد الإرسال';
      return;
    }
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    timerEl.textContent = toArabic(m) + ':' + toArabic(s);
    seconds--;
  };

  tick();
  setInterval(tick, 1000);
})();
</script>

